cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

// WMMA tile size
#define WMMA_M 16
#define WMMA_N 16
#define WMMA_K 16

// Block tile (must be multiple of WMMA tile)
#define BLOCK_M 64   // rows of C computed by a block
#define BLOCK_N 32   // cols of C computed by a block
#define BLOCK_K WMMA_K

// ---------------------------------------------------------------------
// Kernel
// ---------------------------------------------------------------------
__global__ void wmma_gemm_half(const __half* __restrict__ A,
                               const __half* __restrict__ B,
                               __half* __restrict__ C,
                               int N) {
    // block coordinates
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // each block has 256 threads (8 warps)
    // map one warp -> one WMMA fragment (16x16)
    int warpId = threadIdx.y;                 // 0..7 (one warp per row of threads)
    int laneId = threadIdx.x;                 // 0..31 within warp

    // compute warp's position inside the block tile
    const int warpsPerBlockRow = BLOCK_M / WMMA_M;   // 4
    const int warpsPerBlockCol = BLOCK_N / WMMA_N;   // 2
    int warpRow = warpId / warpsPerBlockCol;         // 0..3
    int warpCol = warpId % warpsPerBlockCol;         // 0..1

    // shared memory for a tile of A and B
    extern __shared__ __half shared[];
    __half* shmemA = shared;                                          // BLOCK_M * BLOCK_K
    __half* shmemB = shared + BLOCK_M * BLOCK_K;                       // BLOCK_K * BLOCK_N

    // accumulator fragment in FP32
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> c_frag;
    wmma::fill_fragment(c_frag, 0.0f);

    // loop over K dimension tiles
    for (int tk = 0; tk < N; tk += BLOCK_K) {
        // -----------------------------------------------------------------
        // Load A tile into shared memory (row‑major)
        // Each thread loads one element of A and one of B
        // -----------------------------------------------------------------
        int aRow = blockRow * BLOCK_M + threadIdx.y;   // 0..63
        int aCol = tk + laneId;                        // 0..N‑1

        if (aRow < N && aCol < N) {
            shmemA[threadIdx.y * BLOCK_K + laneId] = A[aRow * N + aCol];
        } else {
            shmemA[threadIdx.y * BLOCK_K + laneId] = __float2half(0.0f);
        }

        int bRow = tk + threadIdx.y;                  // 0..N‑1
        int bCol = blockCol * BLOCK_N + laneId;       // 0..N‑1

        if (bRow < N && bCol < N) {
            shmemB[threadIdx.y * BLOCK_N + laneId] = B[bRow * N + bCol];
        } else {
            shmemB[threadIdx.y * BLOCK_N + laneId] = __float2half(0.0f);
        }

        __syncthreads();

        // -----------------------------------------------------------------
        // Load fragments from shared memory into WMMA fragments
        // -----------------------------------------------------------------
        wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, wmma::row_major> a_frag;
        wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, wmma::col_major> b_frag;

        const __half* tileA = shmemA
            + (warpRow * WMMA_M) * BLOCK_K          // row offset inside A tile
            + (warpCol * WMMA_K);                   // col offset inside A tile

        const __half* tileB = shmemB
            + (warpRow * WMMA_K) * BLOCK_N          // row offset inside B tile
            + (warpCol * WMMA_N);                   // col offset inside B tile

        wmma::load_matrix_sync(a_frag, tileA, BLOCK_K);
        wmma::load_matrix_sync(b_frag, tileB, BLOCK_N);

        // matrix multiply‑accumulate
        wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);

        __syncthreads();   // ensure shared memory not overwritten before next tile
    }

    // -----------------------------------------------------------------
    // Write C tile back to global memory (row‑major)
    // -----------------------------------------------------------------
    int cRow = blockRow * BLOCK_M + warpRow * WMMA_M;
    int cCol = blockCol * BLOCK_N + warpCol * WMMA_N;

    if (cRow < N && cCol < N) {
        __half* cTile = C + cRow * N + cCol;
        wmma::store_matrix_sync(cTile, c_frag, N, wmma::mem_row_major);
    }
}

// ---------------------------------------------------------------------
// Wrapper
// ---------------------------------------------------------------------
torch::Tensor wmma_gemm_half(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Expect 2‑D tensors");
    TORCH_CHECK(A.size(0) == A.size(1) && B.size(0) == B.size(1) &&
                A.size(0) == B.size(0), "Only square matrices of equal size are supported");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "Inputs must be fp16");

    int N = A.size(0);
    auto C = torch::empty_like(A);

    const int threads_x = 32;          // one warp
    const int threads_y = 8;           // 8 warps per block
    dim3 blockDim(threads_x, threads_y);
    dim3 gridDim((N + BLOCK_N - 1) / BLOCK_N,
                 (N + BLOCK_M - 1) / BLOCK_M);

    size_t shared_bytes = (BLOCK_M * BLOCK_K + BLOCK_K * BLOCK_N) * sizeof(__half);

    wmma_gemm_half<<<gridDim, blockDim, shared_bytes, at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
        N);

    return C;
}
